sys_script_include.script:
// B.5 ITFRoutingResolver
//
// Script Include class body. Loaded via Now.include().
// Class.create pattern: do NOT import Glide APIs here — they are auto-available
// in the Script Include execution context.
//
// Resolves the department's executive approver, OPM analyst and OPM group from
// the Department Routing decision table.
//
// MANDATORY CORRECTION against §14 B.5, do not revert: getDecisions (plural),
// not getDecision. The real Brazil API returns an ARRAY, and the answer VALUES
// are NOT readable off the returned object (it is a snapshot whose
// `result_elements` reads back empty). Take resp[0].sys_id, re-query
// sys_decision_multi_result, and read gr.result_elements.<name>.
var ITFRoutingResolver = Class.create();
ITFRoutingResolver.prototype = {
    initialize: function () {},

    resolve: function (departmentId) {
        var dtId = gs.getProperty('x_snc_sas_positi_0.dt_department_routing');
        if (!dtId) {
            return {
                director: '',
                analyst: '',
                group: '',
                error: 'Decision table property not set',
            };
        }

        var inputs = {};
        inputs.department = departmentId;

        // CORRECTION — getDecisions (plural), returns an array.
        var resp = new sn_dt.DecisionTableAPI().getDecisions(dtId, inputs);
        if (!resp || !resp.length || !resp[0].sys_id) {
            return { director: '', analyst: '', group: '', error: 'No decision returned' };
        }

        // The object getDecisions() returns is a SNAPSHOT, not a live
        // GlideRecord: its `result_elements` reads back as an empty string.
        // Re-query the answer record and read its variable container instead.
        // Verified on Brazil.
        var ans = new GlideRecord('sys_decision_multi_result');
        if (!ans.get(resp[0].sys_id.toString())) {
            return { director: '', analyst: '', group: '', error: 'Answer record not found' };
        }

        // Read values BEFORE testing them. A GlideElement from a variable
        // container is not reliably truthy, so a `!r.opm_group` style guard
        // rejects perfectly good answers.
        function read(container, name) {
            try {
                return container[name].toString();
            } catch (e) {
                return '';
            }
        }

        var r = ans.result_elements;
        var director = read(r, 'director_approver');
        var analyst = read(r, 'opm_analyst');
        var group = read(r, 'opm_group');

        if (!director && !analyst && !group) {
            return { director: '', analyst: '', group: '', error: 'Answer has no values' };
        }
        return { director: director, analyst: analyst, group: group, error: '' };
    },

    type: 'ITFRoutingResolver',
};
